INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Wirtschaftlichkeit IT-Systeme > TCO, ROI, Amortisation
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Berücksichtigt der TCO (Total Cost of Ownership) nur die Anschaffungskosten eines IT-Systems?', 2, '[{"text": "Nein", "correct": true, "because": "TCO umfasst alle Kosten über die Lebensdauer"}, {"text": "Ja", "correct": false, "because": "TCO ist umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist der ROI (Return on Investment) ein Indikator für die Rentabilität eines IT-Systems?', 2, '[{"text": "Ja", "correct": true, "because": "Misst Ertrag im Verhältnis zu Kosten"}, {"text": "Nein", "correct": false, "because": "ROI ist zentraler Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Amortisation eines IT-Systems ohne Berücksichtigung der Nutzungsdauer berechnet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Nutzungsdauer ist wesentlich für die Berechnung"}, {"text": "Ja", "correct": false, "because": "Dauer ist erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Wartungskosten ein Teil des TCO?', 2, '[{"text": "Ja", "correct": true, "because": "TCO umfasst Betriebs- und Wartungskosten"}, {"text": "Nein", "correct": false, "because": "Wartung ist enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein positiver ROI auch bei hohen TCO-Werten erreicht werden?', 2, '[{"text": "Ja", "correct": true, "because": "Hoher Ertrag kann Kosten übersteigen"}, {"text": "Nein", "correct": false, "because": "Mögliches Szenario"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart gehört typischerweise zum TCO eines IT-Systems?', 3, '[{"text": "Betriebskosten", "correct": true, "because": "Teil der Gesamtkosten"}, {"text": "Marketingkosten", "correct": false, "because": "Nicht systembezogen"}, {"text": "Transportkosten", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst den ROI eines IT-Systems maßgeblich?', 2, '[{"text": "Erzielte Einsparungen", "correct": true, "because": "Steigert den Ertrag"}, {"text": "Farbe des Systems", "correct": false, "because": "Ästhetisch"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Zeitspanne beschreibt die Amortisation eines IT-Systems?', 2, '[{"text": "Zeit bis Kostendeckung", "correct": true, "because": "Punkt der Refinanzierung"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}, {"text": "Garantiezeit", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wird für die Berechnung des TCO nicht benötigt?', 3, '[{"text": "Farbe der Hardware", "correct": true, "because": "Ästhetisch, nicht kostenrelevant"}, {"text": "Anschaffungskosten", "correct": false, "because": "Teil des TCO"}, {"text": "Wartungskosten", "correct": false, "because": "Teil des TCO"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Amortisationsberechnung?', 2, '[{"text": "Feststellung der Refinanzierungszeit", "correct": true, "because": "Zeigt Break-even-Punkt"}, {"text": "Kostensenkung", "correct": false, "because": "Indirekt"}, {"text": "Markenwahl", "correct": false, "because": "Irrelevant"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Kostenarten gehören zum TCO eines IT-Systems?', 4, '[{"text": "Anschaffungskosten", "correct": true, "because": "Erwerb des Systems"}, {"text": "Betriebskosten", "correct": true, "because": "Laufende Kosten"}, {"text": "Wartungskosten", "correct": true, "because": "Instandhaltung"}, {"text": "Werbekosten", "correct": false, "because": "Nicht systembezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen den ROI eines IT-Systems?', 3, '[{"text": "Einsparungen", "correct": true, "because": "Erhöht Ertrag"}, {"text": "Investitionskosten", "correct": true, "because": "Basis der Berechnung"}, {"text": "Produktivität", "correct": true, "because": "Steigert Nutzen"}, {"text": "Farbe der Hardware", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente sind für die Amortisationsberechnung wichtig?', 3, '[{"text": "Investitionskosten", "correct": true, "because": "Grundlage der Kalkulation"}, {"text": "Nutzungsdauer", "correct": true, "because": "Bestimmt Zeitrahmen"}, {"text": "Erträge", "correct": true, "because": "Beeinflusst Refinanzierung"}, {"text": "Lieferzeit", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Berechnung des TCO?', 4, '[{"text": "Transparente Kosteneinsicht", "correct": true, "because": "Zeigt Gesamtkosten"}, {"text": "Bessere Planung", "correct": true, "because": "Langfristige Sicht"}, {"text": "Entscheidungsgrundlage", "correct": true, "because": "Vergleich möglich"}, {"text": "Schnelle Installation", "correct": false, "because": "Unabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte verbessern den ROI eines IT-Systems?', 3, '[{"text": "Kostensenkung", "correct": true, "because": "Reduziert Investition"}, {"text": "Effizienzsteigerung", "correct": true, "because": "Erhöht Ertrag"}, {"text": "Lange Nutzungsdauer", "correct": true, "because": "Verteilt Kosten"}, {"text": "Minimale Funktionen", "correct": false, "because": "Einschränkt Nutzen"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Der TCO umfasst Wartungskosten. b) Der ROI wird nur durch Anschaffungskosten bestimmt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TCO ja, ROI umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die Amortisation zeigt die Zeit bis zur Kostendeckung. b) TCO bezieht sich nur auf die Nutzungsdauer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Amortisation ja, TCO umfassender"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein hoher ROI zeigt eine rentable Investition. b) Amortisation ist unabhängig von den Erträgen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ROI ja, Erträge wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) TCO hilft bei der langfristigen Kostenplanung. b) ROI wird ohne Berücksichtigung der Investition berechnet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "TCO ja, Investition nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Amortisation berücksichtigt die Nutzungsdauer. b) TCO ist nur für kleine Systeme relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dauer ja, TCO allgemein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

